<script setup>import {ref,onMounted} from 'vue';import {api} from '../services/api';import {useRoute} from 'vue-router';const route=useRoute(),order=ref(null),error=ref('');onMounted(async()=>{try{const r=await api.orders();order.value=r.data.find(o=>o.id===route.params.id)||{id:route.params.id,number:'N/A',total:0,items:[]}}catch(e){error.value=e.message}});</script>
<template><section class="confirmation"><div v-if="error" class="empty">{{error}}</div><div v-else-if="order"><div class="checkmark">✓</div><span class="eyebrow">ORDER CONFIRMED</span><h1>Thank you for your purchase.</h1><p>We are processing your order.</p><b>Order #{{order.number}}</b><div class="order-details"><p v-if="order.items"><strong>Items:</strong> {{order.items.length}} product(s)</p><p v-if="order.total"><strong>Total:</strong> ${{order.total.toFixed(2)}}</p><p v-if="order.status"><strong>Status:</strong> {{order.status}}</p></div><div class="actions"><router-link class="btn primary" to="/shop">Continue Shopping</router-link></div></div></section></template>
